      applyToShorts: !!settings.applyToShorts,
      applyToChannelPlayer: !!settings.applyToChannelPlayer,
      applyToMobile: !!settings.applyToMobile,
      applyToTwitch: !!settings.applyToTwitch,
      applyToKick: !!settings.applyToKick,
